mapper.sql:
WHERE p.deleted = FALSE

    AND (p.plan_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR p.plan_name ILIKE #{q.keywordLike} ESCAPE '\')


    AND p.course_id = #{q.courseId}


    AND p.owner_no = #{q.ownerNo}


    AND p.plan_state = #{q.planState}



    AND p.plan_end_date >= #{q.dateFrom}


    AND p.plan_start_date <= #{q.dateTo}



    AND calc_light(
          p.plan_end_date,
          p.last_state_changed_at,
          (SELECT t.blue_days FROM cfg_warning_threshold t
            WHERE t.object_type = '培训计划' AND t.deleted = FALSE),
          (SELECT t.red_days FROM cfg_warning_threshold t
            WHERE t.object_type = '培训计划' AND t.deleted = FALSE),
          p.plan_state = '已完成'
        ) = #{q.light}
